package com.congosecvision.mobile;

import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.content.*;import android.security.keystore.KeyGenParameterSpec;import android.security.keystore.KeyProperties;import android.util.Base64;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import org.json.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.net.*;import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends Activity {
  final int BG=0xff07111f,PANEL=0xff101e30,PANEL2=0xff14263b,LINE=0xff233b54,WHITE=0xffedf6ff,MUTED=0xff91a9c2,CYAN=0xff35d9ee,BLUE=0xff268bff,GREEN=0xff24d6a0,RED=0xffff637c,AMBER=0xffffc15c,VIOLET=0xff9b7bff;
  LinearLayout root,content,nav; TextView connection; EditText urlField,tokenField; String base="",token=""; String page="dashboard"; ExecutorService pool=Executors.newSingleThreadExecutor(); Handler handler=new Handler(); JSONObject overview=new JSONObject(); JSONArray assets=new JSONArray(),incidents=new JSONArray(),events=new JSONArray(),vulns=new JSONArray(),findings=new JSONArray(),approvals=new JSONArray(),workflows=new JSONArray(),team=new JSONArray();
  public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);base=pref("server");token=readSecret();if(!base.isEmpty()&&!token.isEmpty())refreshAll();render();}
  int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);} GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(18));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
  TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(4),0,dp(4));return t;}
  LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
  void pad(View v,int a){v.setPadding(dp(a),dp(a),dp(a),dp(a));} void gap(LinearLayout l,int h){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
  TextView button(String text,Runnable action){TextView b=label(text,13,WHITE,true);b.setGravity(Gravity.CENTER);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setBackground(shape(BLUE,0));b.setOnClickListener(v->action.run());return b;}
  void render(){root=column();root.setBackgroundColor(BG);setContentView(root);LinearLayout header=row();header.setPadding(dp(18),dp(12),dp(18),dp(12));TextView brand=label("◈  CONGO SEC VISION",18,CYAN,true);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));connection=label("● Hors ligne",11,AMBER,true);header.addView(connection);root.addView(header);ScrollView scroll=new ScrollView(this);content=column();content.setPadding(dp(18),dp(8),dp(18),dp(22));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));nav=row();nav.setPadding(dp(5),dp(7),dp(5),dp(8));nav.setBackgroundColor(0xff0b1727);String[][] tabs={{"⌂","Accueil","dashboard"},{"▦","Actifs","assets"},{"◉","Alertes","events"},{"◇","Incidents","incidents"},{"⋯","Plus","more"}};for(String[] t:tabs){TextView x=label(t[0]+"\n"+t[1],11,page.equals(t[2])?CYAN:MUTED,true);x.setGravity(Gravity.CENTER);x.setPadding(0,dp(7),0,dp(7));x.setOnClickListener(v->{page=t[2];renderPage();});nav.addView(x,new LinearLayout.LayoutParams(0,-2,1));}root.addView(nav);renderPage();}
  void renderPage(){content.removeAllViews();if(page.equals("dashboard"))dashboard();else if(page.equals("assets"))assetPage();else if(page.equals("events"))eventPage();else if(page.equals("incidents"))incidentPage();else morePage();}
  void title(String over,String main,String sub){content.addView(label(over.toUpperCase(),10,CYAN,true));content.addView(label(main,27,WHITE,true));content.addView(label(sub,13,MUTED,false));gap(content,12);}
  void card(String head,String body,int accent){LinearLayout c=column();c.setPadding(dp(15),dp(13),dp(15),dp(13));c.setBackground(shape(PANEL,LINE));c.addView(label(head,13,MUTED,true));c.addView(label(body,23,accent,true));content.addView(c,new LinearLayout.LayoutParams(-1,-2));gap(content,9);}
  void section(String s){content.addView(label(s,16,WHITE,true));gap(content,7);}
  void dashboard(){title("Security operations / Mobile SOC","Vue générale","Surveillance de l'environnement connecté.");if(base.isEmpty()||token.isEmpty()){setupCard();return;}LinearLayout r=row();r.setWeightSum(2);mini(r,"Actifs",overview.optInt("assets_total"),CYAN);mini(r,"En ligne",overview.optInt("assets_online"),GREEN);content.addView(r);r=row();mini(r,"Vulnérabilités",overview.optInt("open_vulnerabilities"),AMBER);mini(r,"Critiques",overview.optInt("critical_vulnerabilities"),RED);content.addView(r);gap(content,12);TextView refresh=button("↻  Actualiser les données",()->refreshAll());content.addView(refresh);gap(content,15);section("État du SOC");card("API",connection==null?"Connexion en cours":(base.isEmpty()?"Non configurée":"Connectée / dernière synchronisation"),GREEN);section("Activité récente");if(events.length()==0)empty("Aucun événement remonté pour le moment.");else for(int i=0;i<Math.min(5,events.length());i++)eventCard(events.optJSONObject(i));section("Incidents prioritaires");if(incidents.length()==0)empty("Aucun incident enregistré.");else for(int i=0;i<Math.min(4,incidents.length());i++)incidentCard(incidents.optJSONObject(i));}
  void mini(LinearLayout r,String name,int value,int color){LinearLayout c=column();c.setPadding(dp(13),dp(12),dp(8),dp(12));c.setBackground(shape(PANEL,LINE));c.addView(label(name,11,MUTED,true));c.addView(label(""+value,24,color,true));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(3),0,dp(3),dp(7));r.addView(c,p);}
  void setupCard(){section("Connexion à votre SOC");content.addView(label("Adresse HTTPS de l'API",12,MUTED,true));urlField=new EditText(this);urlField.setSingleLine();urlField.setTextColor(WHITE);urlField.setHintTextColor(MUTED);urlField.setHint("https://soc.votre-domaine.tld");urlField.setText(base);urlField.setBackground(shape(PANEL2,LINE));content.addView(urlField);gap(content,8);content.addView(label("Jeton administrateur",12,MUTED,true));tokenField=new EditText(this);tokenField.setSingleLine();tokenField.setTextColor(WHITE);tokenField.setHintTextColor(MUTED);tokenField.setHint("ADMIN_TOKEN");tokenField.setInputType(129);tokenField.setBackground(shape(PANEL2,LINE));content.addView(tokenField);gap(content,12);content.addView(button("CONNECTER AU SOC",()->connect()));gap(content,8);empty("Le jeton est chiffré avec Android Keystore sur cet appareil. HTTPS est obligatoire pour les serveurs distants.");}
  void assetPage(){title("Inventory management","Actifs & machines","Inventaire réel envoyé par les agents.");content.addView(button("↻  Actualiser",()->refreshAll()));gap(content,10);if(assets.length()==0)empty("Aucun agent enrôlé. Les machines apparaîtront après leur premier enrôlement.");for(int i=0;i<assets.length();i++){JSONObject a=assets.optJSONObject(i);if(a==null)continue;String ip=a.optJSONArray("ip_addresses")==null?"":a.optJSONArray("ip_addresses").toString();card(a.optString("hostname","Machine"),a.optString("platform")+"  •  "+(a.optBoolean("online")?"EN LIGNE":"HORS LIGNE")+"\nCPU "+a.optString("cpu_percent","—")+"%  ·  RAM "+a.optString("memory_percent","—")+"%\n"+ip,a.optBoolean("online")?GREEN:AMBER);}}
  void eventPage(){title("Threat intelligence","Alertes & événements","Événements réellement collectés par les agents.");content.addView(button("↻  Actualiser",()->refreshAll()));gap(content,10);if(events.length()==0)empty("Aucun événement collecté.");for(int i=0;i<events.length();i++)eventCard(events.optJSONObject(i));gap(content,12);section("Constats d'analyse IA");if(findings.length()==0)empty("Aucun constat disponible.");for(int i=0;i<findings.length();i++){JSONObject f=findings.optJSONObject(i);card(f.optString("title","Constat"),f.optString("severity")+" · "+f.optString("details"),severity(f.optString("severity")));}}
  void eventCard(JSONObject e){if(e==null)return;card(e.optString("category","Événement")+" · "+e.optString("severity","info"),e.optString("message")+"\n"+e.optString("created_at"),severity(e.optString("severity")));}
  int severity(String s){switch(s.toLowerCase()){case "critical":return RED;case "high":return 0xffff8b62;case "medium":return AMBER;case "low":return CYAN;default:return MUTED;}}
  void incidentPage(){title("Incident response","Gestion des incidents","Suivi et mise à jour du cycle de vie.");content.addView(button("＋  Nouvel incident",()->newIncident()));gap(content,8);content.addView(button("↻  Actualiser",()->refreshAll()));gap(content,10);if(incidents.length()==0)empty("Aucun incident. Vous pouvez en créer un ou corréler les constats.");for(int i=0;i<incidents.length();i++)incidentCard(incidents.optJSONObject(i));gap(content,10);content.addView(button("Créer des incidents depuis les constats",()->post("/api/incidents/from-findings",new JSONObject(),r->{toast("Incidents créés : "+r.optInt("created"));refreshAll();})));}
  void incidentCard(JSONObject x){if(x==null)return;LinearLayout c=column();c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackground(shape(PANEL,LINE));c.addView(label("#"+x.optInt("id")+"  ·  "+x.optString("severity").toUpperCase(),11,severity(x.optString("severity")),true));c.addView(label(x.optString("title"),16,WHITE,true));c.addView(label(x.optString("description"),12,MUTED,false));c.addView(label("Statut : "+x.optString("status")+"  ·  "+x.optString("assignee","Non assigné"),11,CYAN,false));TextView edit=button("Modifier le statut",()->statusDialog(x));c.addView(edit);content.addView(c);gap(content,9);}
  void statusDialog(JSONObject x){String[] opts={"open","investigating","contained","resolved","closed"};new AlertDialog.Builder(this).setTitle("Statut de l'incident #"+x.optInt("id")).setItems(opts,(d,w)->{JSONObject b=new JSONObject();try{b.put("status",opts[w]);}catch(Exception ignored){}patch("/api/incidents/"+x.optInt("id"),b,r->{toast("Incident mis à jour");refreshAll();});}).setNegativeButton("Annuler",null).show();}
  void newIncident(){LinearLayout form=column();EditText t=field("Titre de l'incident"),desc=field("Description / contexte");form.addView(t);form.addView(desc);new AlertDialog.Builder(this).setTitle("Créer un incident").setView(form).setPositiveButton("Créer",(d,w)->{JSONObject b=new JSONObject();try{b.put("title",t.getText().toString());b.put("description",desc.getText().toString());b.put("severity","medium");}catch(Exception ignored){}post("/api/incidents",b,r->{toast("Incident créé");refreshAll();});}).setNegativeButton("Annuler",null).show();}
  EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(WHITE);e.setHintTextColor(MUTED);return e;}
  void morePage(){title("SOC toolkit","Centre de contrôle","Outils avancés et gouvernance.");tool("Analyse IA","Analyser les événements reçus",()->post("/api/ai/analyze",new JSONObject(),r->{showJson("Analyse IA",r.toString());}));tool("Synchronisation CVE","Recherche de candidats NVD",()->post("/api/cve/sync",new JSONObject(),r->{showJson("Synchronisation CVE",r.toString());refreshAll();}));tool("Diagnostics","Contrôler les inventaires",()->post("/api/diagnostics/inventory",new JSONObject(),r->showJson("Diagnostics",r.toString())));tool("Topologie réseau","Voir les nœuds et relations",()->getOne("/api/topology","Topologie réseau"));tool("Vulnérabilités","Consulter les CVE",()->getOne("/api/vulnerabilities","Vulnérabilités"));tool("Approbations","Demandes et décisions",()->getOne("/api/approvals","Approbations"));tool("Workflows","Automatisations descriptives",()->getOne("/api/workflows","Workflows"));tool("Équipe","Registre des membres",()->getOne("/api/team","Équipe"));tool("Journal d'audit","Actions administratives",()->getOne("/api/audit","Journal d'audit"));tool("Exporter les actifs CSV","Télécharger l'inventaire",()->downloadCsv());tool("Paramètres de connexion","Serveur et jeton",()->{page="settings";settings();});tool("État de sécurité","Configuration API",()->getOne("/api/security/status","Sécurité"));}
  void tool(String name,String desc,Runnable run){LinearLayout c=column();c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackground(shape(PANEL,LINE));c.addView(label(name,15,WHITE,true));c.addView(label(desc,11,MUTED,false));c.addView(button("Ouvrir",run));content.addView(c);gap(content,8);}
  void settings(){content.removeAllViews();title("Configuration","Connexion SOC","Les informations sensibles restent chiffrées sur l'appareil.");setupCard();}
  void empty(String s){TextView t=label(s,13,MUTED,false);t.setPadding(dp(15),dp(18),dp(15),dp(18));t.setBackground(shape(PANEL,LINE));content.addView(t);gap(content,9);}
  void connect(){base=urlField.getText().toString().trim().replaceAll("/+$","");token=tokenField.getText().toString().trim();if(!base.startsWith("https://")){toast("Utilise une URL HTTPS pour le serveur distant.");return;}if(token.isEmpty()){toast("Jeton administrateur requis.");return;}savePref("server",base);writeSecret(token);((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(tokenField.getWindowToken(),0);refreshAll();}
  void refreshAll(){if(base.isEmpty()||token.isEmpty()){handler.post(()->{if(connection!=null)connection.setText("● Non configuré");});return;}handler.post(()->{if(connection!=null)connection.setText("● Synchronisation…");});pool.execute(()->{try{JSONObject o=(JSONObject)request("GET","/api/overview",null);JSONArray a=(JSONArray)request("GET","/api/assets",null),i=(JSONArray)request("GET","/api/incidents",null),e=(JSONArray)request("GET","/api/events",null),v=(JSONArray)request("GET","/api/vulnerabilities",null),f=(JSONArray)request("GET","/api/ai/findings",null);overview=o;assets=a;incidents=i;events=e;vulns=v;findings=f;handler.post(()->{connection.setText("● SOC connecté");connection.setTextColor(GREEN);renderPage();});}catch(Exception ex){handler.post(()->{connection.setText("● Erreur API");connection.setTextColor(RED);toast(ex.getMessage());});}});}
  Object request(String method,String path,JSONObject body)throws Exception{URL u=new URL(base+path);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(25000);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Accept","application/json");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream os=c.getOutputStream()){os.write(body.toString().getBytes("UTF-8"));}}int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);c.disconnect();String s=out.toString("UTF-8");if(code>=400)throw new Exception("HTTP "+code+" : "+s);if(s.startsWith("{"))return new JSONObject(s);if(s.startsWith("["))return new JSONArray(s);return s;}
  void post(String path,JSONObject body,java.util.function.Consumer<JSONObject> done){call("POST",path,body,done);}void patch(String path,JSONObject body,java.util.function.Consumer<JSONObject> done){call("PATCH",path,body,done);}void call(String method,String path,JSONObject body,java.util.function.Consumer<JSONObject> done){pool.execute(()->{try{JSONObject r=(JSONObject)request(method,path,body);handler.post(()->done.accept(r));}catch(Exception e){handler.post(()->toast(e.getMessage()));}});}
  void getOne(String path,String name){pool.execute(()->{try{Object o=request("GET",path,null);handler.post(()->showJson(name,o.toString()));}catch(Exception e){handler.post(()->toast(e.getMessage()));}});}
  void showJson(String name,String value){TextView t=label(value,12,WHITE,false);ScrollView s=new ScrollView(this);s.addView(t);new AlertDialog.Builder(this).setTitle(name).setView(s).setPositiveButton("Fermer",null).show();}
  void downloadCsv(){pool.execute(()->{try{Object s=request("GET","/api/reports/export.csv",null);String csv=String.valueOf(s);File f=new File(getExternalFilesDir(null),"congo-sec-vision-assets.csv");try(FileOutputStream o=new FileOutputStream(f)){o.write(csv.getBytes("UTF-8"));}handler.post(()->new AlertDialog.Builder(this).setTitle("Export terminé").setMessage("Fichier enregistré dans : "+f.getAbsolutePath()).setPositiveButton("OK",null).show());}catch(Exception e){handler.post(()->toast(e.getMessage()));}});}
  void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
  String pref(String k){return getSharedPreferences("csv",0).getString(k,"");}void savePref(String k,String v){getSharedPreferences("csv",0).edit().putString(k,v).apply();}
  SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("csv.mobile.token")){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("csv.mobile.token",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (SecretKey)ks.getKey("csv.mobile.token",null);}
  void writeSecret(String s){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[] iv=c.getIV(),enc=c.doFinal(s.getBytes("UTF-8"));byte[] all=new byte[iv.length+enc.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(enc,0,all,iv.length,enc.length);savePref("token.enc",Base64.encodeToString(all,Base64.NO_WRAP));}catch(Exception e){toast("Stockage sécurisé impossible : "+e.getMessage());}}
  String readSecret(){try{String x=pref("token.enc");if(x.isEmpty())return "";byte[] all=Base64.decode(x,Base64.NO_WRAP),iv=Arrays.copyOfRange(all,0,12),enc=Arrays.copyOfRange(all,12,all.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,iv));return new String(c.doFinal(enc),"UTF-8");}catch(Exception e){return "";}}
  @Override protected void onDestroy(){super.onDestroy();pool.shutdownNow();}
}
